"""Fail when docs are stale, broken, unindexed, or missing status metadata."""
from __future__ import annotations

import re
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parents[1]
DOCS_DIR = PROJECT_ROOT / "docs"
LINK_RE = re.compile(r"\[[^\]]*\]\(([^)]+)\)")
BACKTICK_MD_RE = re.compile(r"`([^`]+\.md)`")
STATUS_VALUES = {"current", "historical", "superseded", "proposal"}
CURRENT_KEYS = {"status", "owner", "last_verified", "verified_against"}
# Generated by scripts/update_current_state.py; its banner is the status.
HEADER_EXEMPT = {"docs/CURRENT-STATE.md"}
# User-authored scratch summary, not part of the current doc set.
IGNORED_ROOT = {"SOLUTION_SUMMARY.md"}


def _front_matter(text: str) -> dict[str, str]:
    if not text.startswith("---\n"):
        return {}
    end = text.find("\n---", 4)
    if end < 0:
        return {}
    data: dict[str, str] = {}
    for line in text[4:end].splitlines():
        if ":" not in line or line.lstrip().startswith("#"):
            continue
        key, value = line.split(":", 1)
        data[key.strip()] = value.strip().strip("\"'")
    return data


def _doc_paths() -> list[Path]:
    roots = [
        path
        for path in sorted(PROJECT_ROOT.glob("*.md"))
        if path.name not in IGNORED_ROOT
    ]
    docs = sorted(DOCS_DIR.glob("*.md"))
    return roots + docs


def _strip_fenced_code(text: str) -> str:
    lines: list[str] = []
    fenced = False
    for line in text.splitlines():
        if line.lstrip().startswith("```"):
            fenced = not fenced
            continue
        if not fenced:
            lines.append(line)
    return "\n".join(lines)


def _check_file(path: Path) -> list[str]:
    errors: list[str] = []
    text = path.read_text(encoding="utf-8-sig").replace("\r\n", "\n")
    relative = path.relative_to(PROJECT_ROOT).as_posix()
    meta = _front_matter(text)
    status = meta.get("status", "")

    if relative not in HEADER_EXEMPT and status != "historical" and "/Users/" in text:
        errors.append(f"{relative}: current doc contains a local absolute path")

    if relative not in HEADER_EXEMPT:
        if not status:
            errors.append(f"{relative}: missing status front matter")
        elif status not in STATUS_VALUES:
            errors.append(f"{relative}: unknown status {status!r}")
        elif status == "current":
            missing = sorted(CURRENT_KEYS - set(meta))
            if missing:
                errors.append(
                    f"{relative}: current doc missing {', '.join(missing)}"
                )
        if path.name == "HANDOFF.md":
            body = text
            if text.startswith("---\n"):
                end = text.find("\n---", 4)
                if end >= 0:
                    body = text[end + 4 :]
            if len([line for line in body.splitlines() if line.strip()]) > 1:
                errors.append(f"{relative}: root HANDOFF must stay a one-line pointer")

    for target in LINK_RE.findall(_strip_fenced_code(text)):
        target = target.strip()
        if not target or target.startswith(("http://", "https://", "mailto:", "#")):
            continue
        target = target.split("#", 1)[0].strip()
        if not target or " " in target:
            continue
        # Ignore inline examples such as [text](url) or regex fragments; real
        # doc links are relative paths with a separator or an extension.
        if "/" not in target and "." not in target:
            continue
        if not (path.parent / target).exists():
            errors.append(f"{relative}: broken link {target}")
    return errors


def _check_index() -> list[str]:
    """Every docs/*.md is listed in docs/README.md; every listed doc exists."""
    errors: list[str] = []
    index_path = DOCS_DIR / "README.md"
    if not index_path.exists():
        return ["docs/README.md: missing"]
    index = index_path.read_text(encoding="utf-8-sig").replace("\r\n", "\n")
    listed = {Path(name).name for name in BACKTICK_MD_RE.findall(index)}

    for path in sorted(DOCS_DIR.glob("*.md")):
        if path.name == "README.md":
            continue
        if path.name not in listed:
            errors.append(f"docs/README.md: does not index {path.name}")

    for name in sorted(listed):
        if not name.endswith(".md") or "*" in name:
            continue
        if name in {"README.md", "HANDOFF-2026-05.md"}:
            continue
        if (DOCS_DIR / name).is_file() or (PROJECT_ROOT / name).is_file():
            continue
        errors.append(f"docs/README.md: lists missing doc {name}")
    return errors


def _check_history_status() -> list[str]:
    errors: list[str] = []
    history = DOCS_DIR / "history"
    for sub in ("plans", "specs", "reports"):
        for path in sorted((history / sub).glob("*.md")):
            text = path.read_text(encoding="utf-8-sig").replace("\r\n", "\n")
            if not text.startswith("---\nstatus: historical"):
                errors.append(f"{path}: missing historical status header")
    return errors


def main() -> int:
    errors: list[str] = []
    paths = _doc_paths()
    for path in paths:
        errors.extend(_check_file(path))
    errors.extend(_check_index())
    errors.extend(_check_history_status())
    if errors:
        print("\n".join(errors))
        return 1
    current = 0
    for path in paths:
        relative = path.relative_to(PROJECT_ROOT).as_posix()
        if relative in HEADER_EXEMPT:
            continue
        if _front_matter(path.read_text(encoding="utf-8-sig")).get("status") == "current":
            current += 1
    print(f"docs ok ({current} current docs, {len(paths)} files checked)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
